const prompt = msg.prompt || (typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload));
let cmd = `agy -p ${JSON.stringify(prompt)} --dangerously-skip-permissions`;
if (msg.schema) {
    const schemaStr = typeof msg.schema === 'object' ? JSON.stringify(msg.schema) : msg.schema;
    cmd += ` --json-schema ${JSON.stringify(schemaStr)} --output-format json`;
}
msg.payload = cmd;
return msg;

let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    parsed = { response: msg.payload };
}
let result = parsed.structured_output;
if (!result && parsed.response) {
    try { result = typeof parsed.response === 'string' ? JSON.parse(parsed.response) : parsed.response; } catch (e) { result = parsed.response; }
}
msg.payload = result || parsed;
return msg;

const text = typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload);
const hash = crypto.createHash('md5').update(text.trim()).digest('hex');

const cache = flow.get('ai_cache') || {};
const cachedEntry = cache[hash];
const now = Date.now();

// 檢查快取是否存在且在 1 小時 TTL 內
if (cachedEntry && (now - cachedEntry.timestamp < 3600 * 1000)) {
    node.status({ fill: 'green', shape: 'dot', text: '⚡ 快取命中 (0ms)' });
    msg.payload = cachedEntry.data;
    msg.fromCache = true;
    msg.hash = hash;
    return [msg, null]; // 第 1 路: 快取秒回
}

node.status({ fill: 'yellow', shape: 'ring', text: '🔍 快取未命中 (呼叫 AI)' });
msg.hash = hash;
msg.rawText = text;
return [null, msg]; // 第 2 路: 未命中，流向 AI 推理

msg.prompt = `請簡述以下報錯的根因與修復方式：${msg.rawText}`;
msg.schema = { type: 'object', properties: { summary: { type: 'string' }, recommended_action: { type: 'string' } }, required: ['summary', 'recommended_action'] };
return msg;

let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    parsed = { response: msg.payload };
}

const data = parsed.structured_output || parsed.response || parsed;
const hash = msg.hash;

if (hash) {
    const cache = flow.get('ai_cache') || {};
    cache[hash] = {
        data: data,
        timestamp: Date.now()
    };
    flow.set('ai_cache', cache);
    node.status({ fill: 'blue', shape: 'dot', text: '💾 已寫入快取' });
}

msg.payload = data;
msg.fromCache = false;
return msg;
